feed:
  {{ site.title }}
  {% if site.subtitle %}{{ site.subtitle }}{% endif %}


  {{ site.base_url }}/
  {{ updated }}
  {{ site.author }}
{% for p in pages %}

    {{ p.title }}

    {{ site.base_url }}{{ p.url }}
    {% if p.date %}{{ p.date }}T00:00:00Z{% endif %}
    {{ p.atom_updated }}
    {{ p.description or p.summary }}
    {% for t in p.tags %}{% endfor %}
    {{ p.content }}

{% endfor %}
